#!/usr/bin/env python3
"""Stage7 editorial review report; no experiment execution or historic writes."""
import collections,csv,datetime,json,statistics,sys
from pathlib import Path
from zoneinfo import ZoneInfo
sys.dont_write_bytecode=True
from audit import paired,verify_pair
ROOT=Path(__file__).resolve().parents[4];OUT=Path(__file__).resolve().parent

def read(p):return json.loads(p.read_text())
def table(headers,rows):return '\n'.join(['|'+'|'.join(headers)+'|','|'+'|'.join(['---']*len(headers))+'|']+['|'+'|'.join(map(str,r))+'|' for r in rows])+'\n'
def effect(x,mult=100):return f'{x["mean"]*mult:.3f} [{x["interval95"][0]*mult:.3f}, {x["interval95"][1]*mult:.3f}]'
def main():
 a=read(OUT/'audit/REVIEW-AUDIT.json');assert a['verdict']=='PASS';rows=a['runs'];claims=read(OUT/'CLAIMS.json');old6=read(ROOT/'experiments/003/results/stage6/analysis/RESULTS.json');policies=['wait','reject','retry','drop']
 def group(family,condition):return sorted([r for r in rows if r['family']==family and r['condition']==condition],key=lambda r:r['block'])
 def avg(family,condition,key):return statistics.mean(r[key] for r in group(family,condition))
 context={}
 for label,first,second in [('500ms RETRY−REJECT','a500-retry','a500-reject'),('5s RETRY−WAIT','a5000-retry','a5000-wait')]:
  value=paired([x['U_over_N']-y['U_over_N'] for x,y in zip(group('A',first),group('A',second))]);key=('a500:retry-minus-reject' if label.startswith('500') else 'a5000:retry-minus-wait');verify_pair(value,old6['contrasts'][key]['U_over_N']);context[label]=value
 (OUT/'CONTEXT-CHECKS.json').write_text(json.dumps({'verdict':'PASS','effects':context,'new_performance_runs':0},indent=2)+'\n')
 report=['# Experiment 003 — Stage 7 independent evidence-to-claims review\n',
 '**Verdict: PUBLISH — the evidence is ready to support drafting a narrowly scoped Blog3 using the claim restrictions below.** This is evidence/publication-readiness approval, not approval of an unwritten manuscript. No universal winner, significance claim, causal anomaly explanation or general anti-jitter recommendation is approved. No new performance runs are required for these scoped findings; none were executed. Stop after this review.\n',
 '## Review scope and independence\n',
 f'Reviewed repository revision `{a["reviewed_revision"]}`. Read the three normative specifications, Stage5/6 plans/reports/indexes, frozen inputs, original and B2 ledgers/exclusions, existing offline audits and supporting analysis/source. [New audit](results/stage7/audit.py) separately recomputes U from raw authoritative completions and actual immutable deadlines, original partitions, A/F/S/R, retry conversions, per-phase conditional quantiles, server payload-time, H6 bins/denominators and paired bootstrap arithmetic. It does not import the application’s reconciliation code or historical analysis functions.\n',
 'It additionally replays the archived Python validity functions **in memory**. Those are shared-logic regression checks, not a newly independent protocol validator; existing offline audits also reuse them. “Independent” here means a new raw arithmetic review, not a separate experimental team, external laboratory replication or externally attested execution. Historical audit/report mains were not invoked because some write back into their evidence directories.\n',
 f'[REVIEW-AUDIT.json](results/stage7/audit/REVIEW-AUDIT.json) and [RUNS.csv](results/stage7/audit/RUNS.csv) record70 successful replays:20 primary runs,40 secondary deadline runs and10 secondary B2 runs. All key recalculations match archived results within floating interpolation tolerance. **No primary/secondary populations are pooled.** Every comparison retains five paired blocks;70 runs,2,880 originals/run and roughly a million possible retry pairs in each B2 slowdown window are not alternative independent replication counts.\n',
 '## Integrity, completeness and provenance\n']
 report.append(table(['Check','Result','Limit'],[['Historical content','426 Stage5 +2,230 Stage6 =2,656 source/data/derived file checksums pass before/after audit','Package checksum/control files exclude themselves by design; verified manifest bindings separately'],['Raw coverage','All70 run directories have expected manifests, events, ledgers, clocks, phase/EOF/drain markers, process samples and verification outputs','Reconciliation is embedded in client reports, not always a standalone reconciliation.json; literal layout differs from the normative §7 filename list; equivalent content is present, not an exact-filename-conformance claim'],['Accounting','All2,880 original IDs/run reconcile; attempts correspond; no duplicate execution, missing ACK, UNKNOWN or unaccounted permit in the reviewed runs','Healthy-run evidence does not establish crash durability or exactly-once external effects'],['Validity','All archived reports and in-memory gate replays PASS','Gate code sharing limits independence; new arithmetic provides an additional check'],['Source/config','Every frozen source SHA matches current bytes and its declared Git commit; case seed/order/workload/provenance checked','Git/wall-clock records are internal provenance, not external trusted timestamp attestation'],['Binary provenance','All four unique currently available read-only primary/secondary executable copies match declared hashes; A and B2 reuse identical secondary binaries','Executables are not committed; archive-only readers have hashes/build commands/locks/toolchain records, and must rebuild or obtain copies to recheck bits'],['Exclusions','Primary:none; secondary:no failed measurement run or replacement, one original B plan/block intercepted before traffic','Original interrupted/finalized matrices and boundary proof retained; do not describe a failed or rerun unfavorable measurement'],['Preregistration','Primary/A source+plan committed/frozen before their runs; B2 correction committed/frozen before B2 traffic','B2 is an explicit pre-traffic amendment, not the original unamended seed plan']]))
 report+=['The review touched only Stage7 artifacts. Normative files, application code, earlier reports/measurements and published endpoints remain unchanged. Original primary/secondary binary and source provenance is distinct: primary905e2db; secondary app/A ec97c83; B2 orchestration5c2ccfd with the **ec97c83-built binaries**. Rust uses normal debug builds; Go uses default `go build`, not an asserted Go debug profile.\n',
 '## Primary finding: useful work gained, attempts and conditional tails paid\n',
 'Primary context only: one client/stream, one serial worker,32 total admitted slots including running/cancellation-pending ownership,2s **application-level original deadlines**,80 scheduled originals/s for36s, N2,880, observation39s. The stream RPC has a separate longer context deadline. All-original on-time completion uses the server timestamp<=the original scheduled-time deadline; local Send or ACK timing is not substituted.\n']
 report.append(table(['Policy','Mean U/N','Mean U','Mean A / F','Mean retries','A/N','Mean A/F'],[[p.upper(),f'{avg("PRIMARY",p,"U_over_N")*100:.3f}%',f'{avg("PRIMARY",p,"U"):.1f}',f'{avg("PRIMARY",p,"A"):.1f} / {avg("PRIMARY",p,"F"):.1f}',f'{avg("PRIMARY",p,"retries"):.1f}',f'{avg("PRIMARY",p,"A_over_N"):.4f}',f'{avg("PRIMARY",p,"A_over_F"):.4f}'] for p in policies]))
 report.append('All comparisons below are means of five **within-block** U/N differences, percentage points; bracketed intervals are the prespecified descriptive95% paired-block bootstrap summaries (all3,125 ordered resamples, linear quantiles). No significance/equivalence or population coverage guarantee is inferred.\n')
 report.append(table(['Comparison','Mean pp [descriptive interval]','Five block U count differences'],[[name,effect(value['U_over_N']),', '.join(str(round(x*2880)) for x in value['U_over_N']['values'])] for name,value in a['primary_paired'].items()]))
 total_extra=avg('PRIMARY','retry','A')-avg('PRIMARY','reject','A');gain=avg('PRIMARY','retry','U')-avg('PRIMARY','reject','U')
 report.append(f'**Confirmed primary RETRY gain:**+1.410pp over REJECT,+{gain:.1f} useful originals per2,880 scheduled on average, positive in5/5 blocks. Its own124.8 retry attempts/run equal4.333% of scheduled N and about5% overhead over its first-attempt F. **Total attempts versus REJECT increased only{total_extra:.1f}/run ({100*total_extra/avg("PRIMARY","reject","A"):.3f}%), not124.8**, because RETRY also initiated33.6 fewer distinct originals. A/N=0.9101 can be below1 while retry amplification exists; the missing denominator consists of unsent originals. All recorded initiated attempts in these healthy runs sent/decoded, but Send success alone does not prove useful completion.\n')
 conversions=[len(r['conversion_original_ids']) for r in group('PRIMARY','retry')]
 report.append(f'Raw lifecycles confirm previously refused originals later completed on time: {conversions}. Those IDs are not the net paired gain {[round(x*2880) for x in a["primary_paired"]["retry-minus-reject"]["U_over_N"]["values"]]}; changed admission/sending can displace other originals. Neither an individual counterfactual rescue count nor a retry return-on-investment ratio is established.\n')
